def val(label,expr,key,kp,direct,method,components=None,fn=None,source_part=None):
 p=v(label,expr,key,kp,method);p.update(assessed_8227_demand_ids=direct,component_demand_ids=components or[])
 if fn:p['original_function']=fn
 p['source_part']=source_part or label.split('-')[0]
 return p
def add(n,page,note,parts,tariffs,rep='text',new_item=False,duplicate=None):
 direct=sorted({d for p in parts for d in p.get('assessed_8227_demand_ids',[])})
 components=sorted({d for p in parts for d in p.get('component_demand_ids',[])}-set(direct))
 inputs=[p['original_function']for p in parts if 'original_function'in p]
 r=h.add('Revision-Exercise-6',n,page,note,parts,direct,components,new_item=new_item,powers=inputs)
 r.update(representation=rep,exam_style=True,exam_style_basis='Source Revision Exercise6, within section6.3 Exam-Style Questions. Printed total30 and part tariffs checked on PDF318–319; this is textbook practice, not an official examination award table.',source_part_tariffs=tariffs,source_total_marks=sum(tariffs.values()),source_marks_kind='Textbook printed tariffs; no official criterion schedule supplied.',mapping_rationale='Retain each requested result and its source part. Multiple response outputs within one printed part share that part tariff; never add its marks twice. Repeated source questions are occurrences, not additional problem-type breadth.')
 if duplicate:r.update(source_duplicate_of=duplicate,duplicate_basis='Same original function, givens and requested mathematical results as the cited earlier textbook item; revision adds printed tariffs rather than a new structure.')
 for p in parts:
  p['given_representation']=rep
  assert p['source_part']in tariffs
 if new_item:new[-1].update(item_kind='exercise',exam_style=True,exam_style_basis=r['exam_style_basis'])
 return r

